Evaluate the JavaScript procedural FPS map generator implementation on a scale of 0-10 points:

**Map Generation Quality (4 points)**: Does it create realistic, playable FPS maps with proper room layouts, corridors, and tactical positions? Are maps varied and interesting rather than random noise?

**Connectivity & Features (3 points)**: Does it properly implement flood-fill to ensure all areas are reachable? Are spawn points and weapon pickups strategically placed?

**Performance & Interface (2 points)**: Does it generate maps efficiently at 60 FPS? Does the "Generate New Map" button work with a clear legend?

**Code Architecture (1 point)**: Is the code well-structured with proper procedural generation algorithms and error handling?

Solution A: function generateMap(canvasId, w = 500, h = 500) {
  const canvas = document.getElementById(canvasId);
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext("2d");
  ctx.fillStyle = "black";
  const map = Array.from({ length: h }, () => new Array(w).fill(0));

  const directions = [[0, -1], [0, 1], [-1, 0], [1, 0]];

  function carvePath(x, y, len) {
    let dx = 0;
    let dy = 0;
    for (let i = 1; i < len; i++) {
      const dir = Math.floor(Math.random() * 4);
      [dx, dy] = directions[dir];
      carve(x + dx, y + dy);
      carve(x + i * dx, y + i * dy);
    }
  }

  function carve(x, y) {
    if (x >= 0 && x < w && y >= 0 && y < h && map[y][x] === 0) {
      map[y][x] = 1;
      ctx.fillRect(x, y, 1, 1);
    }
  }

  function floodFill(x, y, target) {
    const stack = [[x, y]];
    while (stack.length > 0) {
      const [xx, yy] = stack.pop();
      map[yy][xx] = target;
      for (const [dx, dy] of directions) {
        const newX = xx + dx;
        const newY = yy + dy;
        if (newX >= 0 && newX < w && newY >= 0 && newY < h && map[newY][newX] === 0) {
          stack.push([newX, newY]);
        }
      }
    }
  }

  function generate() {
    ctx.clearRect(0, 0, w, h);
    for (let i = 0; i < 10; i++) {
      carve(Math.floor(Math.random() * w), Math.floor(Math.random() * h), Math.floor(Math.random() * 20) + 1);
    }
    for (let i = 0; i < 5; i++) {
      floodFill(Math.floor(Math.random() * w), Math.floor(Math.random() * h), 2);
    }
    for (let i = 0; i < 5; i++) {
      floodFill(Math.floor(Math.random() * w), Math.floor(Math.random() * h), 3);
    }
  }

  generate();

  const button = document.createElement("button");
  button.innerHTML = "Generate New Map";
  button.onclick = generate;
  document.body.appendChild(button);
}

